/nix/store/q9gk8vgqbcs39yd3q0a8y48rdz53rmbw-pi-coding-agent-0.87.1/lib/node_modules/pi-monorepo/node_modules/@earendil-works/pi-ai/dist/providers/openrouter-images.d.ts.map:1:{"version":3,"file":"openrouter-images.d.ts","sourceRoot":"","sources":["../../src/providers/openrouter-images.ts"],"names":[],"mappings":"AAIA,OAAO,EAAwB,KAAK,cAAc,EAAE,MAAM,qBAAqB,CAAC;AAEhF,wBAAgB,wBAAwB,IAAI,cAAc,CAezD","sourcesContent":["import { openrouterImagesApi } from "../api/openrouter-images.lazy.ts";
import { envApiKeyAuth, lazyOAuth } from "../auth/helpers.ts";
import { loadOpenRouterOAuth } from "../auth/oauth/load.ts";
import { IMAGE_MODELS } from "../image-models.generated.ts";
import { createImagesProvider, type ImagesProvider } from "../images-models.ts";

export function openrouterImagesProvider(): ImagesProvider {
	return createImagesProvider({
		id: "openrouter",
		name: "OpenRouter",
		auth: {
			apiKey: envApiKeyAuth("OpenRouter API key", ["OPENROUTER_API_KEY"]),
			oauth: lazyOAuth({
				name: "OpenRouter OAuth",
				loginLabel: "Sign in with OpenRouter",
				load: loadOpenRouterOAuth,
			}),
		},
		models: Object.values(IMAGE_MODELS.openrouter),
		api: openrouterImagesApi(),
	});
}
